async (page) => {
    const { execSync } = require('child_process');

    try {
        // Make the script executable
        execSync('chmod +x /tmp/mcp-workspace/network_monitor.sh', { encoding: 'utf-8' });
        console.log('Script made executable');

        // Start the monitoring script in the background
        execSync('nohup /tmp/mcp-workspace/network_monitor.sh > /tmp/mcp-workspace/monitor_output.log 2>&1 &', { encoding: 'utf-8' });
        console.log('Monitoring script started in background');

        // Wait a moment for the script to start
        await new Promise(resolve => setTimeout(resolve, 1000));

        // Check if process is running
        const ps = execSync('ps aux | grep network_monitor.sh | grep -v grep', { encoding: 'utf-8' });
        console.log('Process status:\n' + ps);

        return 'Script started successfully';
    } catch (error) {
        console.error('Error:', error.message);
        return 'Error: ' + error.message;
    }
}
